    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 3px;
}

::deep .emoji-option:hover {
    background: #36393f;
}

/* Message Input */
::deep .message-input-area,
::deep .thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

::deep .message-input,
::deep .thread-input {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

::deep .message-input:focus,
::deep .thread-input:focus {
    outline: none;
    box-shadow: 0 0 0 1px #7289da;
}

::deep .send-btn {
    background: #7289da;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .send-btn:hover:not(:disabled) {
    background: #677bc4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h5 {
    margin: 0;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #36393f;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .thread-root-message .message-author {
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b9bbbe;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #36393f;
}
"}

